// ---------- Woot 店铺数据并入 (并入 US/NA, 美元; 按子 ASIN 归到对应产品) ----------
// 逐日记录精确落到当天(自然月内直接累加); 周/月汇总记录按自然月重叠天数比例分摊。未识别 ASIN → 伪 ASIN WOOT-STORE。
const WOOT_ASIN = 'WOOT-STORE';
function wootEntriesLocal(){ try { const a = JSON.parse(localStorage.getItem('pc_woot') || '[]'); return Array.isArray(a) ? a : []; } catch(e){ return []; } }
function wootLen(a, b){ return Math.round((new Date(b+'T00:00:00Z') - new Date(a+'T00:00:00Z')) / 86400000) + 1; }
function wootAllocByAsin(es, qs, qe){
  const out = new Map();
  for (const en of es) {
    const L = wootLen(en.start, en.end); if (!L) continue;
    const s = en.start > qs ? en.start : qs, e = en.end < qe ? en.end : qe;
    if (s > e) continue;
    const k = (Math.round((new Date(e+'T00:00:00Z') - new Date(s+'T00:00:00Z')) / 86400000) + 1) / L;
    const key = en.asin || WOOT_ASIN;
    let o = out.get(key);
    if (!o) { o = { orders:0, sales:0, adCost:0, adClicks:0, adOrders:0, adImpr:0, adSales:0 }; out.set(key, o); }
    const m = en.metrics || {};
    o.orders += (+m.orders || 0) * k;
    o.sales += (+m.sales || 0) * k; o.adCost += (+m.adCost || 0) * k; o.adClicks += (+m.adClicks || 0) * k;
    o.adOrders += (+m.adOrders || 0) * k; o.adImpr += (+m.adImpr || 0) * k; o.adSales += (+m.adSales || 0) * k;
  }
  return out;
}
(function injectWootMonthly(){
  const es = wootEntriesLocal();
  if (!es.length) return;
  for (const mo of AMZ_MONTHS) {
    const y = +mo.ym.slice(0,4), m = +mo.ym.slice(5,7);
    const last = new Date(Date.UTC(y, m, 0)).getUTCDate();
    const qs = mo.ym + '-01', qe = mo.ym + '-' + String(last).padStart(2,'0');
    const alloc = wootAllocByAsin(es, qs, qe);
    for (const [asin, al] of alloc) {
      const od = Math.round(al.orders);
      if (!(al.sales || od || al.adCost || al.adClicks || al.adOrders || al.adImpr || al.adSales)) continue;
      AMZ_ROWS.push({ ym: mo.ym, cc: 'US', asin: asin,
        sessions: 0, mob: 0, brw: 0, pv: 0, units: od, b2b: 0, orders: od,
        sales: al.sales, bbSum: 0, bbCnt: 0,
        adClicks: Math.round(al.adClicks), adCost: al.adCost, adOrders: Math.round(al.adOrders), adSales: al.adSales, adImpr: Math.round(al.adImpr), woot: true });
    }
  }
})();

let monthBy = {}, regionSet = new Set(), allRegions = [], asinList = [], seriesList = [];
function rebuildDerived() {
  monthBy = {}; MONTHS.forEach(m => monthBy[m.ym] = m);
  regionSet = new Set(ROWS.map(r => regionOf(r.cc)));
  (TARGETS.targets || []).forEach(t => {
    if (tgtPlat(t) !== selPlatform) return;
    const c = (t.country || '').trim().toUpperCase();
    if (c && c !== 'ALL') regionSet.add(regionOf(c));
  });
  allRegions = REGION_ORDER.filter(r => regionSet.has(r));
  asinList = [...new Set(ROWS.map(r => r.asin))].sort();
  seriesList = [...new Set(ROWS.map(r => rowMeta(r).series))]
    .sort((x, y) => x === '无' ? 1 : (y === '无' ? -1 : x.localeCompare(y, 'zh')));
}
// 注意: rebuildDerived() 必须等 rowMeta/EMBED_MAP 就绪后再调用(定义在下方映射段之后)

// ---------- 产品映射 ----------
const EMBED_MAP = {"catalog":[],"asinMap":[]};
function mapArr() {
  try { const a = JSON.parse(localStorage.getItem('pc_asinmap') || 'null'); if (Array.isArray(a) && a.length) return a; } catch (e) {}
  return (EMBED_MAP && Array.isArray(EMBED_MAP.asinMap)) ? EMBED_MAP.asinMap : [];
}
function metaOf(a, cc) {
  if (a === WOOT_ASIN) return { series: 'Woot', name: 'Woot 店铺活动' };
  if (!a) return { series: '无', name: '无' };
  const arr = mapArr();
  let hit = null, anyHit = null;
  for (const x of arr) {
    if (!x || x.asin !== a) continue;
    anyHit = anyHit || x;
    if ((x.country || 'EU') === cc) { hit = x; break; }
  }
  const m = hit || anyHit;
  if (m) return { series: m.series || '无', name: m.name || '无' };
  return { series: '无', name: '无' };
}
// JoyBuy 行自带系列/产品名(来自 joybuy_sku_map.json)，不走亚马逊 ASIN 映射
function rowMeta(r) {
  if (r && r.jby) return { series: r.series || '其他', name: r.name || '其他' };
  return metaOf(r.asin, regionOf(r.cc));
}
rebuildDerived();   // 派生集合(月份/地区/系列/ASIN)就绪
function namesIn(seriesSet) {
  const names = new Set();
  for (const r of ROWS) { const m = rowMeta(r); if (seriesSet && seriesSet.size && !seriesSet.has(m.series)) continue; names.add(m.name); }
  return [...names].sort((x, y) => x === '无' ? 1 : (y === '无' ? -1 : x.localeCompare(y, 'zh')));
}

